fn step(name: &str, error: LinCapError) -> LinCapError {
    LinCapError::new(format!("{name}: {error}"))
}

macro_rules! match_response {
    ( $code:expr ) => {
        match $code {
            0 => {}
            1 => {
                return Err(LinCapError::new(String::from(
                    "User cancelled the interaction",
                )));
            }
            2 => {
                return Err(LinCapError::new(String::from(
                    "The user interaction was ended in some other way",
                )));
            }
            other => {
                return Err(LinCapError::new(format!(
                    "Unknown portal response code: {other}"
                )))
            }
        }
    };
}

pub struct ScreenCastPortal<'a> {
    proxy: Proxy<'a, &'a Connection>,
    token: String,
    cursor_mode: Option<u32>,
    restore_token: Option<String>,
    version: u32,
    responses: Arc<Mutex<HashMap<String, OrgFreedesktopPortalRequestResponse>>>,
}

impl<'a> ScreenCastPortal<'a> {
    pub fn new(connection: &'a Connection) -> Result<Self, LinCapError> {
        let proxy = connection.with_proxy(
            "org.freedesktop.portal.Desktop",
            "/org/freedesktop/portal/desktop",
            Duration::from_secs(4),
        );

        let token = format!("scap_{}", rand::random::<u16>());

        // Subscribe before any method call: Gamescope can respond immediately.
        let responses = Arc::new(Mutex::new(HashMap::new()));
        let received = responses.clone();
        let mut rule = MatchRule::new_signal("org.freedesktop.portal.Request", "Response");
        rule.sender = Some(BusName::from("org.freedesktop.portal.Desktop"));
        connection.add_match(
            rule,
            move |response: OrgFreedesktopPortalRequestResponse, _, message| {
                if let Some(path) = message.path() {
                    if let Ok(mut pending) = received.lock() {
                        pending.insert(path.to_string(), response);
                    }
                }
                true
            },
        )?;
        Ok(Self {
            proxy,
            token,
            cursor_mode: None,
            restore_token: None,
            version: 1,
            responses,
        })
    }

    fn create_session_args(&self) -> arg::PropMap {
        let mut map = arg::PropMap::new();
        map.insert(
            String::from("handle_token"),
            Variant(Box::new(self.token.clone())),
        );
        map.insert(
            String::from("session_handle_token"),
            Variant(Box::new(self.token.clone())),
        );
        map
    }

    fn select_sources_args(&self) -> Result<arg::PropMap, dbus::Error> {
        let mut map = arg::PropMap::new();
        map.insert(
            String::from("handle_token"),
            Variant(Box::new(self.token.clone())),
        );
        map.insert(String::from("types"), Variant(Box::new(1_u32)));
        map.insert(String::from("multiple"), Variant(Box::new(false)));
        if let Some(cursor_mode) = self.cursor_mode {
            map.insert(String::from("cursor_mode"), Variant(Box::new(cursor_mode)));
        }
        if self.version >= 4 {
            map.insert(String::from("persist_mode"), Variant(Box::new(2_u32)));
        }
        if let Some(token) = self.restore_token.as_ref().filter(|_| self.version >= 4) {
            map.insert(
                String::from("restore_token"),
                Variant(Box::new(token.clone())),
            );
        }
        Ok(map)
    }

    fn handle_req_response(
        &self,
        path: dbus::Path<'static>,
        iterations: usize,
        timeout: Duration,
    ) -> Result<OrgFreedesktopPortalRequestResponse, LinCapError> {
        for _ in 0..iterations {
            if let Some(response) = self.responses.lock()?.remove(&path.to_string()) {
                return Ok(response);
            }
            self.proxy.connection.process(timeout)?;
        }
        if let Some(response) = self.responses.lock()?.remove(&path.to_string()) {
            return Ok(response);
        }
        Err(LinCapError::new(
            "Timed out waiting for the capture portal response".into(),
        ))
    }

    fn create_session(&self) -> Result<dbus::Path, LinCapError> {
        let request_handle = self.proxy.create_session(self.create_session_args())?;

        let response = Arc::new(Mutex::new(None));
        let value = self.handle_req_response(request_handle, 100, Duration::from_millis(100))?;
        *response.lock()? = Some(value);

        if let Some(res) = response.lock()?.take() {
            match_response!(res.response);
            match res
                .results
                .get("session_handle")
                .map(|h| h.0.as_str().map(String::from))
            {
                Some(h) => {
                    let p = dbus::Path::from(match h {
                        Some(p) => p,
                        None => {
                            return Err(LinCapError::new(String::from(
                                "Invalid session_handle received",
                            )))
                        }
                    });

                    return Ok(p);
                }
                None => return Err(LinCapError::new(String::from("Did not get session handle"))),
            }
        }

        Err(LinCapError::new(String::from("Did not get response")))
    }

    fn select_sources(&self, session_handle: dbus::Path) -> Result<(), LinCapError> {
        let request_handle = self
            .proxy
            .select_sources(session_handle, self.select_sources_args()?)?;

        let response = Arc::new(Mutex::new(None));
        let value = self.handle_req_response(
            request_handle,
            1200, // Wait 2 min
            Duration::from_millis(100),
        )?;
        *response.lock()? = Some(value);

        if let Some(res) = response.lock()?.take() {
            match_response!(res.response);
            return Ok(());
        }

        Err(LinCapError::new(String::from("Did not get response")))
    }

    fn start(&self, session_handle: dbus::Path) -> Result<(Stream, Option<String>), LinCapError> {
        let request_handle = self.proxy.start(session_handle, "", PropMap::new())?;

        let response = Arc::new(Mutex::new(None));
        let value = self.handle_req_response(
            request_handle,
            1200, // Allow time for the user's source-selection dialog.
            Duration::from_millis(100),
        )?;
        *response.lock()? = Some(value);

        if let Some(res) = response.lock()?.take() {
            match_response!(res.response);
            match res.results.get("streams") {
                Some(s) => match Stream::from_dbus(s) {
                    Some(s) => {
                        let restore_token = res
                            .results
                            .get("restore_token")
                            .and_then(|token| token.0.as_str())
                            .map(String::from);
                        return Ok((s, restore_token));
                    }
                    None => {
                        return Err(LinCapError::new(String::from(
                            "Failed to extract stream properties",
                        )))
                    }
                },
                None => return Err(LinCapError::new(String::from("Did not get any streams"))),
            }
        }

        Err(LinCapError::new(String::from("Did not get response")))
    }

    pub fn create_stream(&self) -> Result<(Stream, Option<String>, OwnedFd), LinCapError> {
        // Step names go to stderr so a failure says which request the portal ended.
        eprintln!(
            "portal: version {} cursor_mode {:?} restore_token {}",
            self.version,
            self.cursor_mode,
            if self.restore_token.is_some() { "present" } else { "none" }
        );
        let session_handle = self.create_session().map_err(|e| step("CreateSession", e))?;
        eprintln!("portal: CreateSession ok");
        self.select_sources(session_handle.clone()).map_err(|e| step("SelectSources", e))?;
        eprintln!("portal: SelectSources ok");
        let (stream, token) = self.start(session_handle.clone()).map_err(|e| step("Start", e))?;
        eprintln!("portal: Start ok (node {})", stream.pw_node_id());
        let remote = self
            .proxy
            .open_pipe_wire_remote(session_handle, PropMap::new())?;
        // D-Bus transfers ownership of this descriptor to us; PipeWire consumes it once.
        let remote = unsafe { OwnedFd::from_raw_fd(remote.into_fd()) };
        Ok((stream, token, remote))
    }

    pub fn restore_token(mut self, token: Option<String>) -> Self {
        self.restore_token = token;
        self
    }

    pub fn show_cursor(mut self, mode: bool) -> Result<Self, LinCapError> {
        self.version = self.proxy.version()?;
        if self.proxy.available_source_types()? & 1 == 0 {
            return Err(LinCapError::new(
                "The selected session portal offers no monitor capture source".into(),
            ));
        }
        if self.version < 2 {
            return Ok(self);
        }
        let available_modes = self.proxy.available_cursor_modes()?;
        if mode && available_modes & 2 == 2 {
            self.cursor_mode = Some(2);
            return Ok(self);
        }
        if !mode && available_modes & 1 == 1 {
            self.cursor_mode = Some(1);
            return Ok(self);
        }

        // Some portals (notably newer compositor/portal combinations) do not
        // offer the requested cursor mode. Cursor visibility is optional for
        // capture, so use the other supported pixel-stream mode instead of
        // aborting the entire screencast session.
        if available_modes & 1 == 1 {
            self.cursor_mode = Some(1);
            return Ok(self);
        }
        if available_modes & 2 == 2 {
            self.cursor_mode = Some(2);
            return Ok(self);
        }

        // A zero mask means the backend exposes no selectable cursor mode.
        // cursor_mode is optional in SelectSources, so omit it and allow the
        // portal backend to use its default rather than rejecting capture.
        if available_modes == 0 {
            self.cursor_mode = None;
            return Ok(self);
        }

        Err(LinCapError::new("Unsupported cursor mode".to_string()))
    }
}
